create type public.merchant_status as enum ('APPLIED','UNDER_REVIEW','APPROVED','ACTIVE','SUSPENDED','DEACTIVATED');
create type public.application_status as enum ('APPLIED','UNDER_REVIEW','APPROVED','REJECTED','REQUESTED_INFORMATION');
create type public.location_status as enum ('PENDING','APPROVED','ACTIVE','SUSPENDED','DEACTIVATED');
create type public.connectivity_status as enum ('ONLINE','DEGRADED','OFFLINE');
create type public.source_status as enum ('PENDING','VERIFIED','ACTIVE','SUSPENDED','DEACTIVATED');
create type public.agreement_status as enum ('DRAFT','PENDING','ACTIVE','SUSPENDED','TERMINATED');
create type public.revenue_model as enum ('REVENUE_SHARE','PLATFORM_FEE','HYBRID','ENTERPRISE');
create type public.fee_basis as enum ('GROSS','NET_AFTER_PAYMENT_FEES','CUSTOM');
create type public.ledger_status as enum ('PENDING','AVAILABLE','PAID','VOIDED','REFUNDED');
create type public.payout_status as enum ('PENDING','PROCESSING','PAID','FAILED','CANCELLED');

create table public.merchants (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), merchant_number text unique not null, business_name text not null, contact_name text not null, phone text not null, email text not null, status public.merchant_status not null default 'APPLIED', business_address text, city text, region text, country text not null default 'Ghana', verification_status text not null default 'PENDING', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.merchant_applications (id uuid primary key default gen_random_uuid(), application_number text unique not null, applicant_user_id uuid references auth.users(id), merchant_id uuid references public.merchants(id), full_name text not null, business_name text not null, phone text not null, email text not null, business_address text not null, city text not null, region text not null, country text not null default 'Ghana', latitude numeric, longitude numeric, connectivity_provider text not null, connectivity_plan text, equipment_description text, intended_service_area text, payout_information jsonb, verification_information jsonb, status public.application_status not null default 'APPLIED', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by uuid references auth.users(id));
create table public.merchant_locations (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id) on delete cascade, location_number text unique not null, name text not null, address text not null, city text not null, region text not null, country text not null default 'Ghana', latitude numeric, longitude numeric, coverage_area text, status public.location_status not null default 'PENDING', connectivity_status public.connectivity_status not null default 'OFFLINE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.connectivity_sources (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.merchant_locations(id) on delete cascade, provider_name text not null, provider_type text not null, plan_name text, service_reference text, equipment_description text, status public.source_status not null default 'PENDING', metadata jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.merchant_agreements (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id) on delete cascade, agreement_type text not null, status public.agreement_status not null default 'DRAFT', revenue_model public.revenue_model not null, merchant_share_percent numeric check (merchant_share_percent between 0 and 100), stilla_share_percent numeric check (stilla_share_percent between 0 and 100), fee_basis public.fee_basis not null, effective_from timestamptz not null, effective_to timestamptz, terms_summary text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint agreement_shares_valid check (revenue_model <> 'REVENUE_SHARE' or merchant_share_percent + stilla_share_percent = 100));
create table public.location_plans (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.merchant_locations(id) on delete cascade, plan_id uuid not null, active boolean not null default true, price_override numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(location_id, plan_id));
create table public.merchant_earnings (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id), location_id uuid references public.merchant_locations(id), payment_id uuid, gross_amount numeric not null check (gross_amount >= 0), payment_fee numeric not null default 0 check (payment_fee >= 0), net_amount numeric not null, merchant_share_amount numeric not null, stilla_share_amount numeric not null, currency text not null default 'GHS', status public.ledger_status not null default 'PENDING', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.merchant_payouts (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id), amount numeric not null check (amount >= 0), currency text not null default 'GHS', status public.payout_status not null default 'PENDING', provider_reference text, period_start timestamptz, period_end timestamptz, paid_at timestamptz, metadata jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

alter table public.merchants enable row level security;
alter table public.merchant_applications enable row level security;
alter table public.merchant_locations enable row level security;
alter table public.connectivity_sources enable row level security;
alter table public.merchant_agreements enable row level security;
alter table public.location_plans enable row level security;
alter table public.merchant_earnings enable row level security;
alter table public.merchant_payouts enable row level security;
create policy merchants_self_read on public.merchants for select to authenticated using (user_id = (select auth.uid()));
create policy merchant_applications_self_read on public.merchant_applications for select to authenticated using (applicant_user_id = (select auth.uid()) or exists (select 1 from public.merchants m where m.id = merchant_id and m.user_id = (select auth.uid())));
create policy merchant_applications_submit on public.merchant_applications for insert to authenticated with check (applicant_user_id = (select auth.uid()));
create policy merchant_locations_owner_read on public.merchant_locations for select to authenticated using (exists (select 1 from public.merchants m where m.id = merchant_id and m.user_id = (select auth.uid())));
create policy connectivity_owner_read on public.connectivity_sources for select to authenticated using (exists (select 1 from public.merchant_locations l join public.merchants m on m.id = l.merchant_id where l.id = location_id and m.user_id = (select auth.uid())));
create policy agreements_owner_read on public.merchant_agreements for select to authenticated using (exists (select 1 from public.merchants m where m.id = merchant_id and m.user_id = (select auth.uid())));
create policy earnings_owner_read on public.merchant_earnings for select to authenticated using (exists (select 1 from public.merchants m where m.id = merchant_id and m.user_id = (select auth.uid())));
create policy payouts_owner_read on public.merchant_payouts for select to authenticated using (exists (select 1 from public.merchants m where m.id = merchant_id and m.user_id = (select auth.uid())));
